public without sharing class ExchangeRateClient {

    public class ExchangeRateException extends Exception {}

    private static final String ENDPOINT = 'callout:FB_Exchange_Rates/v1/latest';
    private static final Pattern CURRENCY_PATTERN = Pattern.compile('^[A-Z]{3}$');

    public static Map<String, Decimal> getRates(String baseCurrency, Set<String> quoteCurrencies) {
        // --- Validate and normalise base currency ---
        String base = normaliseCode(baseCurrency, 'base currency');

        // --- Validate and normalise quote currencies ---
        if (quoteCurrencies == null || quoteCurrencies.isEmpty()) {
            throw new ExchangeRateException('Quote currency set must not be null or empty.');
        }

        Set<String> normalisedQuotes = new Set<String>();
        for (String qc : quoteCurrencies) {
            normalisedQuotes.add(normaliseCode(qc, 'quote currency'));
        }

        // --- Build and send request (with single retry on 503) ---
        String symbols = String.join(new List<String>(normalisedQuotes), ',');
        String url = ENDPOINT + '?base=' + base + '&symbols=' + symbols;

        HttpRequest req = new HttpRequest();
        req.setEndpoint(url);
        req.setMethod('GET');
        req.setHeader('Accept', 'application/json');

        Http http = new Http();
        HttpResponse res = http.send(req);

        // Retry once if 503
        if (res.getStatusCode() == 503) {
            res = http.send(req);
        }

        // --- Check final status ---
        Integer statusCode = res.getStatusCode();
        if (statusCode != 200) {
            throw new ExchangeRateException('Exchange rate API returned HTTP status ' + statusCode + '.');
        }

        // --- Parse JSON body ---
        Map<String, Object> body;
        try {
            body = (Map<String, Object>) JSON.deserializeUntyped(res.getBody());
        } catch (Exception e) {
            throw new ExchangeRateException('Failed to parse response body as JSON: ' + e.getMessage());
        }

        if (body == null || !body.containsKey('rates') || !(body.get('rates') instanceof Map)) {
            throw new ExchangeRateException('Response body does not contain a valid "rates" object.');
        }

        @SuppressWarnings('casttype')
        Map<String, Object> rates = (Map<String, Object>) body.get('rates');

        // --- Build result: only the requested quote codes ---
        Map<String, Decimal> result = new Map<String, Decimal>();
        for (String qc : normalisedQuotes) {
            if (!rates.containsKey(qc) || rates.get(qc) == null) {
                throw new ExchangeRateException('No rate returned for requested currency: ' + qc);
            }
            Object val = rates.get(qc);
            if (!(val instanceof Decimal)) {
                throw new ExchangeRateException('Rate for currency ' + qc + ' is not a valid number.');
            }
            result.put(qc, (Decimal) val);
        }

        return result;
    }

    private static String normaliseCode(String code, String label) {
        if (code == null) {
            throw new ExchangeRateException(label + ' must not be null.');
        }
        String normalised = code.trim().toUpperCase();
        if (!CURRENCY_PATTERN.match(normalised)) {
            throw new ExchangeRateException(
                label + ' must be exactly three letters A-Z, got: "' + normalised + '".'
            );
        }
        return normalised;
    }
}
