```apex
public class RecordSearchService {

    public class SearchException extends Exception {}

    public static List<SObject> search(
        String objectApiName,
        List<String> fields,
        Map<String, Object> filters,
        String orderByField,
        Integer maxRows
    ) {
        // --- Validate maxRows ---
        if (maxRows == null || maxRows < 1 || maxRows > 200) {
            throw new SearchException('maxRows must be between 1 and 200.');
        }

        // --- Validate fields list ---
        if (fields == null || fields.isEmpty()) {
            throw new SearchException('fields must not be null or empty.');
        }

        // --- Resolve object (case-insensitive) ---
        if (String.isBlank(objectApiName)) {
            throw new SearchException('Object API name must not be blank.');
        }
        Schema.SObjectType sObjType = resolveObject(objectApiName);
        if (sObjType == null) {
            throw new SearchException('Object not found: ' + objectApiName);
        }

        // --- Check object-level FLS ---
        if (!sObjType.getDescribe().isAccessible()) {
            throw new SearchException(
                'Insufficient permissions to read object: ' + sObjType.getDescribe().getName()
            );
        }

        String objectName = sObjType.getDescribe().getName();

        // --- Resolve and validate SELECT fields ---
        List<String> selectFields = new List<String>{'Id'};
        for (String field : fields) {
            if (String.isBlank(field)) {
                throw new SearchException('Field name in fields list must not be blank.');
            }
            Schema.SFieldRelation rel = resolveField(sObjType, field);
            if (rel == null) {
                throw new SearchException('Field not found on ' + objectName + ': ' + field);
            }
            if (!isFieldAccessible(rel)) {
                throw new SearchException(
                    'Insufficient permissions to read field: ' + getCanonicalName(rel)
                );
            }
            String canonical = getCanonicalName(rel);
            if (!selectFields.contains(canonical)) {
                selectFields.add(canonical);
            }
        }

        // --- Resolve and validate filter fields ---
        Map<String, Object> resolvedFilters = new Map<String, Object>();
        if (filters != null) {
            for (String filterKey : filters.keySet()) {
                if (String.isBlank(filterKey)) {
                    throw new SearchException('Filter field name must not be blank.');
                }
                Schema.SFieldRelation rel = resolveField(sObjType, filterKey);
                if (rel == null) {
                    throw new SearchException('Filter field not found on ' + objectName + ': ' + filterKey);
                }
                if (!isFieldAccessible(rel)) {
                    throw new SearchException(
                        'Insufficient permissions to read field: ' + getCanonicalName(rel)
                    );
                }
                if (!isFilterable(rel)) {
                    throw new SearchException(
                        'Field cannot be used in a filter: ' + getCanonicalName(rel)
                    );
                }
                resolvedFilters.put(getCanonicalName(rel), filters.get(filterKey));
            }
        }

        // --- Resolve and validate ORDER BY field ---
        String resolvedOrderBy = null;
        if (String.isNotBlank(orderByField)) {
            Schema.SFieldRelation rel = resolveField(sObjType, orderByField);
            if (rel == null) {
                throw new SearchException(
                    'ORDER BY field not found on ' + objectName + ': ' + orderByField
                );
            }
            if (!isFieldAccessible(rel)) {
                throw new SearchException(
                    'Insufficient permissions to read field: ' + getCanonicalName(rel)
                );
            }
            if (!isSortable(rel)) {
                throw new SearchException(
                    'Field cannot be used in ORDER BY: ' + getCanonicalName(rel)
                );
            }
            resolvedOrderBy = getCanonicalName(rel);
        }

        // --- Build SOQL ---
        StringBuilder soql = new StringBuilder();
        soql.append('SELECT ');
        soql.append(String.join(selectFields, ', '));
        soql.append(' FROM ');
        soql.append(objectName);

        if (!resolvedFilters.isEmpty()) {
            List<String> conditions = new List<String>();
            for (String fieldName : resolvedFilters.keySet()) {
                conditions.add(fieldName + ' = ' + serializeValue(resolvedFilters.get(fieldName)));
            }
            soql.append(' WHERE ');
            soql.append(String.join(conditions, ' AND '));
        }

        if (resolvedOrderBy != null) {
            soql.append(' ORDER BY ');
            soql.append(resolvedOrderBy);
            soql.append(' ASC');
        }

        soql.append(' LIMIT ');
        soql.append(String.valueOf(maxRows));

        try {
            return Database.query(soql.toString());
        } catch (Exception e) {
            throw new SearchException('Query execution failed: ' + e.getMessage());
        }
    }

    // ---------- Private helpers ----------

    private static Schema.SObjectType resolveObject(String objectApiName) {
        Map<String, Schema.SObjectType> globalMap = Schema.getGlobalDescribe();
        Schema.SObjectType result = globalMap.get(objectApiName);
        if (result != null) {
            return result;
        }
        for (String key : globalMap.keySet()) {
            if (key.equalsIgnoreCase(objectApiName)) {
                return globalMap.get(key);
            }
        }
        return null;
    }

    private static Schema.SFieldRelation resolveField(Schema.SObjectType sObjType, String fieldName) {
        Map<String, Schema.SFieldRelation> fieldMap = sObjType.getDescribe().fields.getMap();
        Schema.SFieldRelation result = fieldMap.get(fieldName);
        if (result != null) {
            return result;
        }
        for (String key : fieldMap.keySet()) {
            if (key.equalsIgnoreCase(fieldName)) {
                return fieldMap.get(key);
            }
        }
        return null;
    }

    private static String getCanonicalName(Schema.SFieldRelation rel) {
        if (rel instanceof Schema.SObjectField) {
            return ((Schema.SObjectField) rel).getDescribe().getName();
        }
        return '';
    }

    private static boolean isFieldAccessible(Schema.SFieldRelation rel) {
        if (rel instanceof Schema.SObjectField) {
            return ((Schema.SObjectField) rel).getDescribe().isAccessible();
        }
        return false;
    }

    private static boolean isFilterable(Schema.SFieldRelation rel) {
        if (rel instanceof Schema.SObjectField) {
            Schema.DisplayType type = ((Schema.SObjectField) rel).getDescribe().getType();
            if (type == Schema.DisplayType.Location || type == Schema.DisplayType.Compound) {
                return false;
            }
        }
        return true;
    }

    private static boolean isSortable(Schema.SFieldRelation rel) {
        if (rel instanceof Schema.SObjectField) {
            Schema.DisplayType type = ((Schema.SObjectField) rel).getDescribe().getType();
            if (type == Schema.DisplayType.Location || type == Schema.DisplayType.Compound) {
                return false;
            }
        }
        return true;
    }

    private static String serializeValue(Object value) {
        if (value == null) {
            return 'null';
        }
        if (value instanceof Boolean) {
            return String.valueOf((Boolean) value);
        }
        if (value instanceof Date) {
            return String.valueOf((Date) value);
        }
        if (value instanceof DateTime) {
            return ((DateTime) value).formatGmt('yyyy-MM-dd\'T\'HH:mm:ss\'Z\'');
        }
        if (value instanceof Id) {
            return "'" + String.valueOf((Id) value) + "'";
        }
        if (value instanceof Integer || value instanceof Long || value instanceof Decimal) {
            return String.valueOf(value);
        }
        // Default: treat as string with quote-escaping
        return "'" + String.valueOf(value).replace("'", "''") + "'";
    }
}
