public class OrderPayloadParser {

    public class Order {
        public String orderNumber;
        public Date orderDate;
        public String currencyCode;
        public String customerEmail;
        public List<Line> lines;
        public Decimal total;
    }

    public class Line {
        public String sku;
        public Integer quantity;
        public Decimal unitPrice;
        public Decimal discount;
        public Decimal lineTotal;
    }

    public class PayloadException extends Exception {}

    public static Order parse(String body) {
        if (body == null || String.isBlank(body)) {
            throw new PayloadException('Body is null or blank.');
        }

        Map<String, Object> root;
        try {
            Object parsed = JSON.deserializeUntyped(body);
            if (!(parsed instanceof Map<String, Object>)) {
                throw new PayloadException('Body is not a JSON object.');
            }
            root = (Map<String, Object>) parsed;
        } catch (PayloadException pe) {
            throw pe;
        } catch (Exception e) {
            throw new PayloadException('Invalid JSON: ' + e.getMessage());
        }

        // Validate number
        String number = getString(root, 'number');
        if (number == null || String.isBlank(number)) {
            throw new PayloadException('Missing or blank "number".');
        }

        // Parse date (ISO yyyy-MM-dd)
        Date orderDate = null;
        Object dateVal = root.get('date');
        if (dateVal instanceof String) {
            try {
                orderDate = Date.valueOf((String) dateVal);
            } catch (Exception e) {
                // unparseable date – leave null
            }
        }

        // Parse currency
        String currencyCode = getString(root, 'currency');

        // Parse customer.email
        String customerEmail = null;
        Object custVal = root.get('customer');
        if (custVal instanceof Map<String, Object>) {
            customerEmail = getString((Map<String, Object>) custVal, 'email');
        }

        // Parse lines
        List<Line> lines = new List<Line>();
        Object linesVal = root.get('lines');
        if (linesVal instanceof List<Object>) {
            for (Object item : (List<Object>) linesVal) {
                if (item instanceof Map<String, Object>) {
                    lines.add(parseLine((Map<String, Object>) item));
                }
            }
        }

        // Compute total
        Decimal total = Decimal.ZERO;
        for (Line line : lines) {
            total += line.lineTotal;
        }

        Order order = new Order();
        order.orderNumber = number;
        order.orderDate = orderDate;
        order.currencyCode = currencyCode;
        order.customerEmail = customerEmail;
        order.lines = lines;
        order.total = total;
        return order;
    }

    public static String toAcknowledgement(Order order) {
        Map<String, Object> ack = new Map<String, Object>();
        ack.put('number', order.orderNumber);
        ack.put('status', 'RECEIVED');
        ack.put('lineCount', order.lines == null ? 0 : order.lines.size());
        ack.put('total', order.total);
        return JSON.serialize(ack);
    }

    // ─── helpers ────────────────────────────────────────────────────────────

    private static Line parseLine(Map<String, Object> map) {
        String sku = getString(map, 'sku');
        if (sku == null || String.isBlank(sku)) {
            throw new PayloadException('Line is missing "sku".');
        }

        Integer quantity = getInt(map, 'quantity');
        if (quantity == null || quantity <= 0) {
            throw new PayloadException('Line has missing or non-positive "quantity".');
        }

        Decimal unitPrice = getDecimal(map, 'unitPrice');
        if (unitPrice == null || unitPrice < 0) {
            throw new PayloadException('Line has missing or negative "unitPrice".');
        }

        Decimal discount = getDecimal(map, 'discount');
        if (discount == null) {
            discount = Decimal.ZERO;
        }

        Decimal lineTotal = (quantity * unitPrice * (1 - discount)).setScale(2, RoundingMode.HALF_UP);

        Line line = new Line();
        line.sku = sku;
        line.quantity = quantity;
        line.unitPrice = unitPrice;
        line.discount = discount;
        line.lineTotal = lineTotal;
        return line;
    }

    private static String getString(Map<String, Object> map, String key) {
        Object val = map.get(key);
        if (val instanceof String) {
            return (String) val;
        }
        return null;
    }

    private static Integer getInt(Map<String, Object> map, String key) {
        Object val = map.get(key);
        if (val instanceof Integer) {
            return (Integer) val;
        }
        if (val instanceof Decimal) {
            Decimal d = (Decimal) val;
            if (d == d.setScale(0, RoundingMode.DOWN)) {
                return d.intValue();
            }
        }
        return null;
    }

    private static Decimal getDecimal(Map<String, Object> map, String key) {
        Object val = map.get(key);
        if (val instanceof Integer) {
            return (Decimal) val;
        }
        if (val instanceof Decimal) {
            return (Decimal) val;
        }
        return null;
    }
}
