    // ─── Utility ──────────────────────────────────────────────────────

    /**
     * Checks whether two SObject references point to the same in-memory instance.
     * In Apex there is no == for objects, so we compare via getAnyValue() of a
     * system field that is the same for the same instance. We use a simpler
     * heuristic: if they are the same object reference, all field reads return
     * the same values AND they are the same SObject (not just equal values).
     *
     * The most reliable check in Apex: SObject instances that are the same
     * reference will have the same internal identity. We approximate by
     * checking that the SObject returned as "related" is literally the same
     * object passed to registerNew(SObject) by verifying internal type and
     * that it's not a copy.
     *
     * In practice, since the service creates one Opportunity and passes it to
     * both registerNew(renewal) and registerNew(task, WhatId, renewal), the
     * related object IS the same instance. We verify this by checking that
     * the "related" SObject is not the original opportunity (different Name
     * would suffice, but same-instance is stronger).
     */
    private static Boolean referenceEquals(SObject a, SObject b) {
        if (a == null || b == null) return a == b;
        // In Apex, the == operator on SObject does reference comparison
        // when both sides are SObject (not Id).
        return a == b;
    }
}
