```apex
public class Opportunities extends fflib_SObjectDomain {

    public Opportunities(fflib_SObjectDomain.IConstructable ctx) {
        super(ctx);
        registerSObject(Opportunity.SObjectType);
    }

    public override void onAfterInsert(List<SObject> sobjs) {
        Set<Id> qualifyingIds = new Set<Id>();
        for (SObject sobj : sobjs) {
            Opportunity opp = (Opportunity) sobj;
            if (opp.StageName == 'Closed Won') {
                qualifyingIds.add(opp.Id);
            }
        }
        callStartFulfilment(qualifyingIds);
    }

    public override void onAfterUpdate(List<SObject> sobjs) {
        Set<Id> qualifyingIds = new Set<Id>();
        for (SObject sobj : sobjs) {
            Opportunity opp = (Opportunity) sobj;
            Opportunity oldOpp = (Opportunity) Trigger.oldMap.get(opp.Id);
            if (opp.StageName == 'Closed Won' && oldOpp.StageName != 'Closed Won') {
                qualifyingIds.add(opp.Id);
            }
        }
        callStartFulfilment(qualifyingIds);
    }

    private void callStartFulfilment(Set<Id> ids) {
        if (!ids.isEmpty()) {
            IOpportunityFulfilmentService service =
                Application.Service.newInstance(IOpportunityFulfilmentService.class);
            service.startFulfilment(ids);
        }
    }

    public class Constructor implements fflib_SObjectDomain.IConstructable {
        public Constructor() {}
        public fflib_SObjectDomain construct() {
            return new Opportunities(this);
        }
    }
}
