public class CasePriorityHandler {

    public static void handleBeforeInsert(List<Case> newCases) {
        // Collect the distinct AccountIds we need to look up.
        Set<Id> accountIds = new Set<Id>();
        for (Case c : newCases) {
            if (c.AccountId != null) {
                accountIds.add(c.AccountId);
            }
        }

        // Nothing to do if no case references an account.
        if (accountIds.isEmpty()) {
            return;
        }

        // Single SOQL fetch – safe for batches up to the 200-record limit.
        Map<Id, Account> accountMap =
            new Map<Id, Account>([SELECT Id, Rating FROM Account WHERE Id IN :accountIds]);

        // Apply the priority rule; all other cases are left untouched.
        for (Case c : newCases) {
            Account acc = accountMap.get(c.AccountId);
            if (acc != null && acc.Rating == 'Hot') {
                c.Priority = 'High';
            }
        }
    }
}
