public class DealEventPublisher {

    /**
     * Salesforce governor limit: maximum platform events publishable per transaction.
     */
    private static final Integer MAX_EVENTS_PER_TXN = 50;

    /**
     * Publishes a Deal_Stage_Change__e platform event for each opportunity in the input list.
     *
     * Returns one SaveResult per event, in the same order as the input list,
     * so the caller can identify exactly which event (if any) failed.
     *
     * Note: At most 50 events can be published per transaction. If more than 50
     * opportunities are supplied, only the first 50 are published and a WARN log
     * is emitted. The caller (trigger handler) should chunk or queue overflow
     * records to avoid silent data loss.
     *
     * @param opportunities List of opportunities to publish stage-change events for.
     * @return List of SaveResult, one per published event, in input order.
     */
    public static List<Database.SaveResult> publishStageChanges(List<Opportunity> opportunities) {
        if (opportunities == null || opportunities.isEmpty()) {
            return new List<Database.SaveResult>();
        }

        // Guard against exceeding the per-transaction platform event limit
        Integer total = opportunities.size();
        if (total > MAX_EVENTS_PER_TXN) {
            System.debug(LoggingLevel.WARN,
                'DealEventPublisher.publishStageChanges: received ' + total +
                ' opportunities but the platform-event limit is ' + MAX_EVENTS_PER_TXN +
                ' per transaction. Publishing only the first ' + MAX_EVENTS_PER_TXN +
                '. Caller should chunk or queue the remainder.');
            opportunities = opportunities.subList(0, MAX_EVENTS_PER_TXN);
        }

        // Build events in the same order as the (possibly capped) input list
        List<Deal_Stage_Change__e> events = new List<Deal_Stage_Change__e>();
        for (Opportunity opp : opportunities) {
            events.add(new Deal_Stage_Change__e(
                Opportunity_Id__c = opp.Id,
                Stage__c          = opp.StageName,
                Amount__c         = opp.Amount
            ));
        }

        // Single batched publish; results are returned in the same order as the
        // events list, giving per-event success/failure visibility.
        return EventBus.publish(events);
    }
}
