import { LightningElement, wire } from 'lwc';
import {
    registerListener,
    unregisterListener,
    publish,
    APPLICATION_SCOPE,
    MessageContext
} from 'lightning/messageService';
import { Account_Selected__c } from '@salesforce/messageChannel/Account_Selected__c';

export default class AccountDetailsPanel extends LightningElement {
    selectedRecordId = null;

    _messageContext;
    _subscription;

    @wire(MessageContext)
    wireMessageContext(context) {
        this._messageContext = context;
        if (context && !this._subscription) {
            this._subscribe();
        }
    }

    connectedCallback() {
        if (this._messageContext && !this._subscription) {
            this._subscribe();
        }
    }

    disconnectedCallback() {
        this._unsubscribe();
    }

    get hasSelection() {
        return !!this.selectedRecordId;
    }

    _subscribe() {
        this._subscription = registerListener(
            Account_Selected__c,
            (message) => this._handleMessage(message),
            APPLICATION_SCOPE
        );
    }

    _unsubscribe() {
        if (this._subscription) {
            unregisterListener(this._subscription);
            this._subscription = null;
        }
    }

    _handleMessage(message) {
        this.selectedRecordId = message.recordId || null;
    }

    handleClear() {
        publish(Account_Selected__c, { recordId: null }, APPLICATION_SCOPE);
    }
}
