import { api } from 'lwc';

let uidCounter = 0;

export default class StatusListbox extends LightningElement {
    @api label;

    _options = [];
    @api
    get options() {
        return this._options;
    }
    set options(val) {
        this._options = val || [];
    }

    _value;
    _activeIndex = 0;
    _uid;

    connectedCallback() {
        this._uid = ++uidCounter;
        const idx = this._findIndexByValue(this._value);
        this._activeIndex = idx !== -1 ? idx : 0;
    }

    get value() {
        return this._value;
    }

    @api
    set value(val) {
        this._value = val;
        const idx = this._findIndexByValue(val);
        if (idx !== -1) {
            this._activeIndex = idx;
        }
    }

    _findIndexByValue(val) {
        if (!val) return -1;
        return this._options.findIndex((o) => o.value === val);
    }

    get activeId() {
        if (this._options.length === 0) return '';
        const idx =
            this._activeIndex >= 0 && this._activeIndex < this._options.length
                ? this._activeIndex
                : 0;
        return `slb-opt-${this._uid}-${idx}`;
    }

    get optionIds() {
        return this._options.map((_, i) => `slb-opt-${this._uid}-${i}`);
    }

    handleKeydown(event) {
        const { key } = event;
        const handledKeys = ['ArrowDown', 'ArrowUp', 'Home', 'End', 'Enter', ' '];
        if (!handledKeys.includes(key)) return;

        event.preventDefault();

        if (this._options.length === 0) return;

        switch (key) {
            case 'ArrowDown':
                if (this._activeIndex < this._options.length - 1) {
                    this._activeIndex++;
                }
                break;
            case 'ArrowUp':
                if (this._activeIndex > 0) {
                    this._activeIndex--;
                }
                break;
            case 'Home':
                this._activeIndex = 0;
                break;
            case 'End':
                this._activeIndex = this._options.length - 1;
                break;
            case 'Enter':
            case ' ':
                this._selectAt(this._activeIndex);
                break;
        }
    }

    handleOptionClick(event) {
        const idx = parseInt(event.currentTarget.dataset.index, 10);
        if (!isNaN(idx) && idx >= 0 && idx < this._options.length) {
            this._activeIndex = idx;
            this._selectAt(idx);
        }
    }

    _selectAt(idx) {
        const option = this._options[idx];
        if (!option) return;
        if (option.value === this._value) return;
        this._value = option.value;
        this.dispatchEvent(
            new CustomEvent('change', { detail: { value: option.value } })
        );
    }
}
