public class GiftService {

    /**
     * Records a gift (donation) that has already been received.
     * Creates a Closed Won Donation Opportunity on the contact's Household,
     * assigns ContactRoles (Donor / Household Member), and records a single Paid Payment.
     *
     * @param contactId  Id of the donor Contact
     * @param amount     Donation amount (must be > 0)
     * @param giftDate   Date the gift was received (used for CloseDate and Payment date)
     * @return           The Id of the newly created Opportunity
     * @throws IllegalArgumentException if contact does not exist or amount is null/zero/negative
     */
    public static Id recordGift(Id contactId, Decimal amount, Date giftDate) {

        // ── Validation ──────────────────────────────────────────────────────────
        if (amount == null || amount <= 0) {
            throw new IllegalArgumentException('Amount must be greater than zero.');
        }

        Contact contact = [
            SELECT Id, FirstName, LastName, AccountId
            FROM Contact
            WHERE Id = :contactId
            LIMIT 1
        ];

        if (contact == null) {
            throw new IllegalArgumentException('Contact does not exist: ' + contactId);
        }

        if (contact.AccountId == null) {
            throw new IllegalArgumentException(
                'Contact ' + contactId + ' is not associated with a Household Account.'
            );
        }

        // ── Resolve household members ───────────────────────────────────────────
        List<Contact> householdMembers = [
            SELECT Id
            FROM Contact
            WHERE AccountId = :contact.AccountId
        ];

        // ── Build Opportunity name: "FirstName LastName Donation yyyy-MM-dd" ──
        String oppName = '';
        if (String.isNotBlank(contact.FirstName)) {
            oppName += contact.FirstName + ' ';
        }
        if (String.isNotBlank(contact.LastName)) {
            oppName += contact.LastName;
        }
        oppName += ' Donation ' + giftDate.format('yyyy-MM-dd');

        // ── Create the Opportunity ──────────────────────────────────────────────
        Opportunity opp = new Opportunity(
            Name      = oppName,
            AccountId = contact.AccountId,
            StageName = 'Closed Won',
            Type      = 'Donation',
            CloseDate = giftDate,
            Amount    = amount,
            Primary__c = contact.Id
        );
        insert opp;

        // ── Create ContactRoles ─────────────────────────────────────────────────
        // The donor contact → 'Donor'; every other household member → 'Household Member'
        List<ContactRole> contactRoles = new List<ContactRole>();
        for (Contact member : householdMembers) {
            Boolean isDonor = (member.Id == contact.Id);
            contactRoles.add(new ContactRole(
                OpportunityId = opp.Id,
                ContactId     = member.Id,
                IsPrimary     = isDonor,
                Role          = isDonor ? 'Donor' : 'Household Member'
            ));
        }
        insert contactRoles;

        // ── Create the single Payment (NPSP Payments) ───────────────────────────
        Payment__c payment = new Payment__c(
            Opportunity__c = opp.Id,
            Amount__c      = amount,
            Date__c        = giftDate,
            Status__c      = 'Paid',
            IsPaid__c      = true
        );
        insert payment;

        return opp.Id;
    }
}
```

**Design notes:**

| Concern | How it's handled |
|---|---|
| **Household linkage** | `Opportunity.AccountId` is set to the contact's `AccountId`; `Primary__c` (NPSP) points to the donor. |
| **ContactRoles** | Every household member gets exactly one role. The donor gets `Donor` + `IsPrimary=true`; all others get `Household Member`. Because we query all members of the household and iterate once, no contact appears twice. |
| **No duplicate payments** | Exactly one `Payment__c` is inserted per call. |
| **NPSP credit** | `Type = 'Donation'` + `Primary__c` + a single paid `Payment__c` is the pattern NPSP's Relationship Grouping and Rollups expect. |
| **Validation** | `IllegalArgumentException` is thrown for null/non-positive amount or missing contact. |
| **Bulk-safety of DML** | Three DML statements total (1 insert opp, 1 bulk insert contact roles, 1 insert payment) — well within governor limits. |

