public class TA_Account_CreateOnboardingTask {
    private Trigger_Action__e _ta;
    private List<Account> _qualifyingAccounts;

    public TA_Account_CreateOnboardingTask(Trigger_Action__e ta) {
        _ta = ta;
        _qualifyingAccounts = new List<Account>();

        if (_ta.isInsert) {
            for (SObject so : _ta.sObjectRecords) {
                Account acc = (Account) so;
                if (acc.Type == 'Customer - Direct' || acc.Type == 'Customer - Channel') {
                    _qualifyingAccounts.add(acc);
                }
            }
        }
    }

    public void execute() {
        if (_qualifyingAccounts.isEmpty()) {
            return;
        }

        Date dueDate = Date.today().addDays(7);
        List<Task> tasksToInsert = new List<Task>();

        for (Account acc : _qualifyingAccounts) {
            tasksToInsert.add(new Task(
                Subject      = 'Onboard new customer',
                WhatId       = acc.Id,
                OwnerId      = acc.OwnerId,
                ActivityDate = dueDate,
                Status       = 'Not Started',
                Priority     = 'Normal'
            ));
        }

        insert tasksToInsert;
    }
}
