public class TA_Contact_PreventDuplicateEmail extends Trigger_Action__c {

    public TA_Contact_PreventDuplicateEmail() {
        // TA__c is populated by the TAF framework
    }

    public override void execute() {
        List<Contact> newContacts = (List<Contact>) Trigger.new;
        List<Contact> oldContacts = (List<Contact>) Trigger.old;
        Boolean isInsert = Trigger.isInsert;

        // Identify relevant contacts and collect their Account IDs
        List<Integer> relevantIdx = new List<Integer>();
        Set<Id> accountIds = new Set<Id>();

        for (Integer i = 0; i < newContacts.size(); i++) {
            Contact c = newContacts[i];
            if (c.AccountId == null || String.isBlank(c.Email)) {
                continue;
            }
            if (!isInsert) {
                Contact old = oldContacts[i];
                if (c.Email == old.Email && c.AccountId == old.AccountId) {
                    continue;
                }
            }
            relevantIdx.add(i);
            accountIds.add(c.AccountId);
        }

        if (accountIds.isEmpty()) {
            return;
        }

        // Single SOQL query – fetch all existing contacts on the affected accounts
        Map<String, Set<Id>> existingByKey = new Map<String, Set<Id>>();
        for (Contact ec : [SELECT Id, AccountId, Email FROM Contact WHERE AccountId IN :accountIds]) {
            if (String.isBlank(ec.Email)) {
                continue;
            }
            String key = ec.AccountId + '|' + String.lower(ec.Email);
            if (!existingByKey.containsKey(key)) {
                existingByKey.put(key, new Set<Id>());
            }
            existingByKey.get(key).add(ec.Id);
        }

        // Evaluate conflicts in trigger order (first accepted, subsequent rejected)
        if (isInsert) {
            Set<String> acceptedKeys = new Set<String>();
            for (Integer idx : relevantIdx) {
                Contact c = newContacts[idx];
                String key = c.AccountId + '|' + String.lower(c.Email);

                if (existingByKey.containsKey(key) || acceptedKeys.contains(key)) {
                    c.addError('Another contact on this account already uses this email address.');
                } else {
                    acceptedKeys.add(key);
                }
            }
        } else {
            Map<String, Id> acceptedKeys = new Map<String, Id>();
            for (Integer idx : relevantIdx) {
                Contact c = newContacts[idx];
                String key = c.AccountId + '|' + String.lower(c.Email);

                Boolean hasConflict = false;

                // Check against DB records (exclude self)
                Set<Id> dbIds = existingByKey.get(key);
                if (dbIds != null) {
                    for (Id dbId : dbIds) {
                        if (dbId != c.Id) {
                            hasConflict = true;
                            break;
                        }
                    }
                }

                // Check against other records in this save (exclude self)
                if (!hasConflict && acceptedKeys.containsKey(key) && acceptedKeys.get(key) != c.Id) {
                    hasConflict = true;
                }

                if (hasConflict) {
                    c.addError('Another contact on this account already uses this email address.');
                } else {
                    acceptedKeys.put(key, c.Id);
                }
            }
        }
    }
}
